import { api } from '@igblsln/store';
export const paymentChatApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        sendVendorPaymentChat: build.mutation({
            query: (body) => ({ url: '/chatbot/', method: 'POST', body }),
        }),
        listVendorPaymentChats: build.query({
            query: () => '/chatbot/history/?flow_type=vendor_payment',
        }),
        getVendorPaymentChat: build.query({
            query: (id) => `/chatbot/${id}/?flow_type=vendor_payment`,
        }),
        deleteVendorPaymentChat: build.mutation({
            query: (id) => ({ url: `/chatbot/${id}/?flow_type=vendor_payment`, method: 'DELETE' }),
        }),
    }),
});
export const { useSendVendorPaymentChatMutation, useLazyListVendorPaymentChatsQuery, useLazyGetVendorPaymentChatQuery, useDeleteVendorPaymentChatMutation, } = paymentChatApi;
